input.command:
cd ~/.claude/projects
for f in $(find ~/.claude/projects -maxdepth 2 -name '*.jsonl' -mtime -1 2>/dev/null | grep -v '/subagents/'); do
  echo "########## $f"
  proj=$(basename $(dirname "$f"))
  echo "PROJECT: $proj"
  # first user text
  python3 - "$f" <<'PY'
import json,sys
f=sys.argv[1]
lines=open(f,encoding='utf-8',errors='replace').read().splitlines()
def txt(m):
    c=m.get('content')
    if isinstance(c,str): return c
    if isinstance(c,list):
        out=[]
        for b in c:
            if isinstance(b,dict):
                if b.get('type')=='text': out.append(b.get('text',''))
                elif b.get('type')=='tool_use': out.append('[tool:'+b.get('name','')+']')
                elif b.get('type')=='tool_result': out.append('[tool_result]')
        return ' '.join(out)
    return ''
msgs=[]
for ln in lines:
    ln=ln.strip()
    if not ln: continue
    try: o=json.loads(ln)
    except: continue
    m=o.get('message')
    if not isinstance(m,dict): continue
    role=m.get('role')
    if role in ('user','assistant'):
        t=txt(m).strip()
        if t: msgs.append((role,t))
# first user
for r,t in msgs:
    if r=='user':
        print("FIRST_USER:", t[:200].replace('\n',' '))
        break
print("MSG_COUNT:", len(msgs))
print("--- last 6 ---")
for r,t in msgs[-6:]:
    print(f"[{r}] {t[:300].replace(chr(10),' ')}")
PY
  echo ""
done

for f in a2adacb8-9f82-40a5-9313-1fbce18ef580 4cbf7e89-bf4a-47b7-a930-5224319f35b2 cd21ce7d-35d7-472b-9494-1e44e0717a91; do
  # find the file
  path=$(find ~/.claude/projects -maxdepth 2 -name "$f.jsonl" | head -1)
  echo "########## $f"
  python3 - "$path" <<'PY'
