    if isinstance(c,list):
        out=[]
        for b in c:
            if isinstance(b,dict) and b.get('type')=='text': out.append(b.get('text',''))
        return ' '.join(out)
    return ''
msgs=[]
for ln in lines:
    ln=ln.strip()
    if not ln: continue
    try:o=json.loads(ln)
    except:continue
    m=o.get('message')
    if not isinstance(m,dict):continue
    if m.get('role') in ('user','assistant'):
        t=txt(m).strip()
        if t: msgs.append((m['role'],t))
# print last assistant message full
for r,t in reversed(msgs):
    if r=='assistant':
        print(t[:1400])
        break
PY
  echo ""
done

